( function ( $ ) {
'use strict';
var i18n = wpfchs_admin.i18n;
function post( action, data ) {
return $.post(
wpfchs_admin.ajax_url,
$.extend( { action: action, nonce: wpfchs_admin.nonce }, data )
);
}
function notice( message, type ) {
var isError = ( 'error' === type );
var $notice = $( '<div class="notice is-dismissible wpfchs-notice"><p></p></div>' )
.addClass( isError ? 'notice-error' : 'notice-success' );
$notice.find( 'p' ).text( message );
$notice.append(
$( '<button type="button" class="notice-dismiss"></button>' ).on( 'click', function () {
$notice.remove();
} )
);
$( '.wpfchs-wrap h1' ).first().after( $notice );
if ( ! isError ) {
window.setTimeout( function () {
$notice.fadeOut( 300, function () {
$( this ).remove();
} );
}, 6000 );
}
return $notice;
}
function pollScan( scanId ) {
post( 'wpfchs_scan_step', { scan_id: scanId } )
.done( function ( response ) {
if ( ! response.success ) {
notice( response.data && response.data.message ? response.data.message : i18n.error, 'error' );
return;
}
var progress = response.data;
var $bar = $( '#wpfchs-progress' );
if ( $bar.length ) {
$bar.find( '.wpfchs-progress-fill' ).css( 'width', progress.percent + '%' );
$bar.find( '.wpfchs-progress-text' ).text(
i18n.scanning + ' ' + progress.scanned + ' / ' + progress.total
);
}
if ( progress.running ) {
pollScan( scanId );
} else if ( 'complete' === progress.status ) {
window.location.reload();
}
} )
.fail( function () {
notice( i18n.scan_failed, 'error' );
} );
}
$( document ).on( 'click', '.wpfchs-start-scan:not(#wpfchs-resume-scan)', function () {
var $button = $( this ).prop( 'disabled', true ).text( i18n.scanning );
var profile = $( '#wpfchs-profile' ).val() || 'revenue_blockers';
var mode = $( this ).data( 'mode' ) === 'incremental' ? 'incremental' : 'full';
post( 'wpfchs_scan_start', { profile: profile, mode: mode } )
.done( function ( response ) {
if ( ! response.success ) {
$button.prop( 'disabled', false );
notice( response.data.message || i18n.error, 'error' );
return;
}
pollScan( response.data.scan_id );
} )
.fail( function () {
$button.prop( 'disabled', false );
notice( i18n.error, 'error' );
} );
} );
$( document ).on( 'click', '#wpfchs-pause-scan', function () {
post( 'wpfchs_scan_control', { scan_id: $( this ).data( 'scan' ), control: 'pause' } ).always( function () {
window.location.reload();
} );
} );
$( document ).on( 'click', '#wpfchs-resume-scan', function () {
var scanId = $( this ).data( 'scan' );
post( 'wpfchs_scan_control', { scan_id: scanId, control: 'resume' } ).done( function () {
pollScan( scanId );
} );
} );
$( document ).on( 'click', '#wpfchs-cancel-scan', function () {
if ( ! window.confirm( i18n.confirm_cancel ) ) {
return;
}
post( 'wpfchs_scan_control', { scan_id: $( this ).data( 'scan' ), control: 'cancel' } ).always( function () {
window.location.reload();
} );
} );
$( function () {
var $progress = $( '#wpfchs-progress' );
if ( $progress.length && 'running' === $progress.data( 'status' ) ) {
pollScan( $progress.data( 'scan' ) );
}
} );
function loadGroupProducts( $group, offset ) {
var $inner = $group.find( '.wpfchs-group-body-inner' );
var $container = $group.closest( '.wpfchs-groups' );
$inner.html( '<p class="wpfchs-panel-empty">' + i18n.loading + '</p>' );
post( 'wpfchs_group_products', {
check_id: $group.data( 'check' ),
offset: offset || 0,
product_cat: $container.data( 'product-cat' ) || 0,
product_type: $container.data( 'product-type' ) || '',
new_since: $container.data( 'new-since' ) || 0
} )
.done( function ( response ) {
if ( response.success ) {
$inner.html( response.data.html ).attr( 'data-loaded', '1' );
} else {
$inner.html( '' );
notice( response.data.message || i18n.error, 'error' );
}
} )
.fail( function () {
$inner.html( '' );
notice( i18n.error, 'error' );
} );
}
function toggleGroup( $group ) {
var $body = $group.find( '.wpfchs-group-body' );
var open = ! $group.hasClass( 'wpfchs-group-open' );
$group.toggleClass( 'wpfchs-group-open', open );
$group.find( '.wpfchs-group-row' ).attr( 'aria-expanded', open ? 'true' : 'false' );
$body.prop( 'hidden', ! open );
if ( open && '1' !== $group.find( '.wpfchs-group-body-inner' ).attr( 'data-loaded' ) ) {
loadGroupProducts( $group, 0 );
}
}
$( document ).on( 'click', '.wpfchs-group-row', function ( event ) {
if ( $( event.target ).is( '.wpfchs-fix-preview' ) ) {
return;
}
toggleGroup( $( this ).closest( '.wpfchs-group' ) );
} );
$( document ).on( 'keydown', '.wpfchs-group-row', function ( event ) {
if ( 'Enter' === event.key || ' ' === event.key ) {
event.preventDefault();
toggleGroup( $( this ).closest( '.wpfchs-group' ) );
}
} );
$( document ).on( 'click', '.wpfchs-page-prev, .wpfchs-page-next', function () {
var $group = $( this ).closest( '.wpfchs-group' );
loadGroupProducts( $group, $( this ).data( 'offset' ) );
} );
function refreshSelection( $body ) {
var total = $body.find( '.wpfchs-select-row' ).length;
var count = $body.find( '.wpfchs-select-row:checked' ).length;
$body.find( '.wpfchs-selected-number' ).text( count );
$body.find( '.wpfchs-selection-count' ).prop( 'hidden', 0 === count );
$body.find( '.wpfchs-action-selected' ).prop( 'hidden', 0 === count );
$body.find( '.wpfchs-select-all' ).prop( 'checked', total > 0 && count === total );
$body.find( '.wpfchs-products-table' ).toggleClass( 'wpfchs-has-selection', count > 0 );
}
function selectedIssueIds( $body ) {
var ids = [];
$body.find( '.wpfchs-select-row:checked' ).each( function () {
ids.push( $( this ).data( 'issue' ) );
} );
return ids;
}
$( document ).on( 'change', '.wpfchs-select-all', function () {
var checked = $( this ).prop( 'checked' );
var $body = $( this ).closest( '.wpfchs-group-body-inner' );
$body.find( '.wpfchs-select-row' ).prop( 'checked', checked );
refreshSelection( $body );
} );
$( document ).on( 'change', '.wpfchs-select-row', function () {
refreshSelection( $( this ).closest( '.wpfchs-group-body-inner' ) );
} );
var lastChecked = null;
$( document ).on( 'click', '.wpfchs-select-row', function ( event ) {
var $rows = $( this ).closest( 'tbody' ).find( '.wpfchs-select-row' );
if ( event.shiftKey && lastChecked && $rows.index( lastChecked ) > -1 ) {
var start = $rows.index( lastChecked );
var end = $rows.index( this );
$rows.slice( Math.min( start, end ), Math.max( start, end ) + 1 )
.prop( 'checked', $( this ).prop( 'checked' ) );
refreshSelection( $( this ).closest( '.wpfchs-group-body-inner' ) );
}
lastChecked = this;
} );
function bulkIgnore( $body, payload, confirmMessage ) {
if ( confirmMessage && ! window.confirm( confirmMessage ) ) {
return;
}
var $group = $body.closest( '.wpfchs-group' );
var $container = $group.closest( '.wpfchs-groups' );
post( 'wpfchs_ignore_bulk', $.extend( {
check_id: $group.data( 'check' ),
product_cat: $container.data( 'product-cat' ) || 0,
product_type: $container.data( 'product-type' ) || '',
new_since: $container.data( 'new-since' ) || 0
}, payload ) ).done( function ( response ) {
if ( ! response.success ) {
notice( response.data.message || i18n.error, 'error' );
return;
}
notice( response.data.message );
window.setTimeout( function () {
window.location.reload();
}, 900 );
} ).fail( function () {
notice( i18n.error, 'error' );
} );
}
$( document ).on( 'click', '.wpfchs-ignore-selected', function () {
var $body = $( this ).closest( '.wpfchs-group-body-inner' );
var ids = selectedIssueIds( $body );
if ( ! ids.length ) {
notice( i18n.no_selection, 'error' );
return;
}
bulkIgnore( $body, { issue_ids: ids }, i18n.confirm_ignore_selected.replace( '%d', ids.length ) );
} );
$( document ).on( 'click', '.wpfchs-ignore-all', function () {
var $body = $( this ).closest( '.wpfchs-group-body-inner' );
bulkIgnore( $body, { all: 1 }, i18n.confirm_ignore_all.replace( '%d', $( this ).data( 'total' ) ) );
} );
$( function () {
var $open = $( '.wpfchs-group-open' );
if ( $open.length ) {
loadGroupProducts( $open.first(), 0 );
}
} );
$( document ).on( 'click', '.wpfchs-ignore-issue', function () {
var $button = $( this );
post( 'wpfchs_ignore_issue', { issue_id: $button.data( 'issue' ) } ).done( function ( response ) {
if ( response.success ) {
$button.closest( 'tr, li' ).fadeOut( 200, function () {
$( this ).remove();
} );
notice( i18n.ignored );
} else {
notice( response.data.message || i18n.error, 'error' );
}
} );
} );
$( document ).on( 'click', '.wpfchs-restore-issue', function () {
var $button = $( this );
post( 'wpfchs_restore_issue', { issue_id: $button.data( 'issue' ) } ).done( function ( response ) {
if ( response.success ) {
$button.closest( 'tr' ).fadeOut( 200, function () {
$( this ).remove();
} );
notice( i18n.restored );
} else {
notice( response.data.message || i18n.error, 'error' );
}
} );
} );
function refreshIgnoredSelection() {
var $panel = $( '.wpfchs-ignored-panel' );
var total = $panel.find( '.wpfchs-ignored-row' ).length;
var count = $panel.find( '.wpfchs-ignored-row:checked' ).length;
$panel.find( '.wpfchs-selected-number' ).text( count );
$panel.find( '.wpfchs-selection-count' ).prop( 'hidden', 0 === count );
$panel.find( '.wpfchs-action-selected' ).prop( 'hidden', 0 === count );
$panel.find( '.wpfchs-ignored-select-all' ).prop( 'checked', total > 0 && count === total );
}
$( document ).on( 'change', '.wpfchs-ignored-select-all', function () {
$( '.wpfchs-ignored-panel' ).find( '.wpfchs-ignored-row' ).prop( 'checked', $( this ).prop( 'checked' ) );
refreshIgnoredSelection();
} );
$( document ).on( 'change', '.wpfchs-ignored-row', refreshIgnoredSelection );
function bulkRestore( payload, confirmMessage ) {
if ( confirmMessage && ! window.confirm( confirmMessage ) ) {
return;
}
post( 'wpfchs_restore_bulk', payload ).done( function ( response ) {
if ( ! response.success ) {
notice( response.data.message || i18n.error, 'error' );
return;
}
notice( response.data.message );
window.setTimeout( function () {
window.location.reload();
}, 900 );
} ).fail( function () {
notice( i18n.error, 'error' );
} );
}
$( document ).on( 'click', '.wpfchs-restore-selected', function () {
var ids = [];
$( '.wpfchs-ignored-panel' ).find( '.wpfchs-ignored-row:checked' ).each( function () {
ids.push( $( this ).data( 'issue' ) );
} );
if ( ! ids.length ) {
notice( i18n.no_selection, 'error' );
return;
}
bulkRestore( { issue_ids: ids }, i18n.confirm_restore_selected.replace( '%d', ids.length ) );
} );
$( document ).on( 'click', '.wpfchs-restore-all', function () {
bulkRestore( { all: 1 }, i18n.confirm_restore_all.replace( '%d', $( this ).data( 'total' ) ) );
} );
function closeModal() {
$( '.wpfchs-modal-overlay' ).remove();
$( document ).off( 'keydown.wpfchsModal' );
}
function openModal( title, bodyHtml, applyLabel, onApply ) {
closeModal();
var $overlay = $( '<div class="wpfchs-modal-overlay" role="dialog" aria-modal="true"></div>' );
var $modal = $( '<div class="wpfchs-modal"></div>' );
var $head = $( '<div class="wpfchs-modal-head"><h2></h2><button type="button" class="wpfchs-modal-close" aria-label="Close">&times;</button></div>' );
$head.find( 'h2' ).text( title );
var $body = $( '<div class="wpfchs-modal-body"></div>' ).html( bodyHtml );
var $foot = $( '<div class="wpfchs-modal-foot"></div>' );
var $cancel = $( '<button type="button" class="button"></button>' ).text( i18n.cancel ).on( 'click', closeModal );
var $apply = $( '<button type="button" class="button button-primary"></button>' ).text( applyLabel ).on( 'click', function () {
$apply.prop( 'disabled', true );
onApply( $apply );
} );
$foot.append( $cancel, $apply );
$modal.append( $head, $body, $foot );
$overlay.append( $modal );
$( 'body' ).append( $overlay );
$head.find( '.wpfchs-modal-close' ).on( 'click', closeModal );
$overlay.on( 'click', function ( event ) {
if ( event.target === $overlay[ 0 ] ) {
closeModal();
}
} );
$( document ).on( 'keydown.wpfchsModal', function ( event ) {
if ( 'Escape' === event.key ) {
closeModal();
}
} );
$apply.trigger( 'focus' );
}
function textParagraph( text ) {
return $( '<p></p>' ).text( text ).prop( 'outerHTML' );
}
function collectFixRequest( $trigger ) {
var checkId = $trigger.data( 'check' );
var request = { check_id: checkId, args: {}, object_ids: [] };
var $group = $trigger.closest( '.wpfchs-group' );
if ( $group.length ) {
$group.find( '.wpfchs-bulk-value' ).each( function () {
request.args[ $( this ).data( 'arg' ) ] = $( this ).val();
} );
if ( $trigger.data( 'selected-only' ) ) {
$group.find( '.wpfchs-select-row:checked' ).each( function () {
request.object_ids.push( $( this ).val() );
} );
}
}
return request;
}
function undoNotice( logId ) {
var $notice = notice( i18n.fixed + ' ' );
var $undo = $( '<button type="button" class="button-link"></button>' ).text( i18n.undo );
$undo.on( 'click', function () {
post( 'wpfchs_fix_undo', { log_id: logId } ).done( function ( response ) {
if ( response.success ) {
notice( i18n.undone );
window.setTimeout( function () {
window.location.reload();
}, 800 );
} else {
notice( response.data.message || i18n.error, 'error' );
}
} );
} );
$notice.find( 'p' ).append( $undo );
}
$( document ).on( 'click', '.wpfchs-fix-preview', function ( event ) {
event.stopPropagation();
var $trigger = $( this );
var request = collectFixRequest( $trigger );
post( 'wpfchs_fix_preview', request ).done( function ( response ) {
if ( ! response.success ) {
notice( response.data.message || i18n.error, 'error' );
return;
}
var data = response.data;
var applyLabel = i18n.apply_to.replace( '%d', data.total );
openModal( data.title, data.html, applyLabel, function ( $apply ) {
post( 'wpfchs_fix_apply', request ).done( function ( applyResponse ) {
closeModal();
if ( applyResponse.success ) {
undoNotice( applyResponse.data.log_id );
window.setTimeout( function () {
window.location.reload();
}, 6000 );
} else {
notice( applyResponse.data.message || i18n.error, 'error' );
}
} ).fail( function () {
$apply.prop( 'disabled', false );
notice( i18n.error, 'error' );
} );
} );
} );
} );
$( document ).on( 'click', '.wpfchs-fix-all-quick-wins', function () {
post( 'wpfchs_preview_quick_wins', {} ).done( function ( response ) {
if ( ! response.success ) {
notice( response.data.message || i18n.error, 'error' );
return;
}
openModal( response.data.title, response.data.html, i18n.apply_fixes, function ( $apply ) {
post( 'wpfchs_fix_all_quick_wins', {} ).done( function ( applyResponse ) {
closeModal();
if ( applyResponse.success ) {
notice( applyResponse.data.message || i18n.fixed );
window.setTimeout( function () {
window.location.reload();
}, 1500 );
} else {
notice( applyResponse.data.message || i18n.error, 'error' );
}
} ).fail( function () {
$apply.prop( 'disabled', false );
notice( i18n.error, 'error' );
} );
} );
} ).fail( function () {
notice( i18n.error, 'error' );
} );
} );
$( document ).on( 'click', '.wpfchs-undo-fix', function () {
var $button = $( this );
post( 'wpfchs_fix_undo', { log_id: $button.data( 'log' ) } ).done( function ( response ) {
if ( response.success ) {
notice( i18n.undone );
window.setTimeout( function () {
window.location.reload();
}, 800 );
} else {
notice( response.data.message || i18n.error, 'error' );
}
} );
} );
$( document ).on( 'click', '.wpfchs-dismiss-rec', function () {
var $line = $( this ).closest( '.wpfchs-recommendation' );
post( 'wpfchs_dismiss_rec', { check_id: $( this ).data( 'check' ) } );
$line.fadeOut( 200, function () {
$( this ).remove();
} );
} );
function submitProfileAction( $button, action, confirmText ) {
if ( confirmText && ! window.confirm( confirmText ) ) {
return;
}
var profile = $button.closest( '.wpfchs-profile-actions' ).data( 'profile' );
var $form = $( '#wpfchs-profile-row-action' );
$form.find( '[name="wpfchs_profiles_action"]' ).val( action );
$form.find( '[name="wpfchs_profile_id"]' ).val( profile );
$form.trigger( 'submit' );
}
$( document ).on( 'click', '.wpfchs-profile-duplicate', function () {
submitProfileAction( $( this ), 'duplicate', '' );
} );
$( document ).on( 'click', '.wpfchs-profile-delete', function () {
submitProfileAction( $( this ), 'delete_custom', i18n.confirm_delete_profile );
} );
$( document ).on( 'click', '.wpfchs-reset-btn', function ( event ) {
if ( ! window.confirm( i18n.confirm_reset ) ) {
event.preventDefault();
}
} );
var logoFrame = null;
$( document ).on( 'click', '.wpfchs-logo-select', function ( event ) {
event.preventDefault();
if ( typeof wp === 'undefined' || ! wp.media ) {
return;
}
if ( logoFrame ) {
logoFrame.open();
return;
}
logoFrame = wp.media( {
title: i18n.choose_logo,
button: { text: i18n.use_logo },
library: { type: 'image' },
multiple: false
} );
logoFrame.on( 'select', function () {
var attachment = logoFrame.state().get( 'selection' ).first().toJSON();
var url = ( attachment.sizes && attachment.sizes.medium ) ? attachment.sizes.medium.url : attachment.url;
var $field = $( '.wpfchs-logo-field' );
$field.find( '#wpfchs-logo-id' ).val( attachment.id );
$field.find( '.wpfchs-logo-preview' ).show().find( 'img' ).attr( 'src', url );
$field.find( '.wpfchs-logo-remove' ).show();
} );
logoFrame.open();
} );
$( document ).on( 'click', '.wpfchs-logo-remove', function ( event ) {
event.preventDefault();
var $field = $( '.wpfchs-logo-field' );
$field.find( '#wpfchs-logo-id' ).val( '' );
$field.find( '.wpfchs-logo-preview' ).hide();
$( this ).hide();
} );
} )( jQuery );
